mapper.select:
SELECT h.apt_name, rc.dong_name, h.house_type, hd.deal_type, hd.deal_amount, hd.deal_date, hd.area, hd.floor FROM house_deal hd INNER JOIN house h ON h.id = hd.house_id INNER JOIN region_code rc ON rc.region_code = h.region_code
AND h.region_code LIKE CONCAT(#{regionCode}, '%')
AND hd.deal_date >= #{startDate}
AND hd.deal_date < #{endDate}
ORDER BY hd.deal_date DESC, hd.id DESC LIMIT #{limit}
